#include <cstdio>
#include <map>
#include <string>
#include <vector>

struct Access { unsigned offset; unsigned size; };
struct Field { unsigned offset; std::string type; std::string name; };

std::vector<Field> guessLayout(const std::vector<Access>& accesses)
{
    std::map<unsigned, unsigned> sizeAt;                    // offset -> largest size, sorted by offset
    for (const Access& a : accesses)
        if (a.size > sizeAt[a.offset]) sizeAt[a.offset] = a.size;

    std::vector<Field> fields;
    unsigned at{ 0 };
    for (const auto& [offset, size] : sizeAt)
    {
        if (offset > at) fields.push_back({ at, "uint8_t[" + std::to_string(offset - at) + "]", "pad" });
        const char* type{ size == 1 ? "uint8_t" : size == 2 ? "uint16_t" : size == 4 ? "uint32_t" : "uint64_t" };
        char name[16];
        std::snprintf(name, sizeof name, "field_%X", offset);
        fields.push_back({ offset, type, name });
        at = offset + size;
    }
    return fields;
}

unitTests:
#include <cstdio>
TEST("the example")
{
    const auto f{ guessLayout({ { 0x0, 4 }, { 0x10, 8 }, { 0xC, 4 }, { 0x0, 4 } }) };
    CHECK_EQ(f.size(), std::size_t{ 4 });
    CHECK_EQ(f[0].offset, 0u); CHECK_EQ(f[0].type, std::string("uint32_t"));
    CHECK_EQ(f[1].offset, 4u); CHECK_EQ(f[1].type, std::string("uint8_t[8]")); CHECK_EQ(f[1].name, std::string("pad"));
    CHECK_EQ(f[2].offset, 0xCu); CHECK_EQ(f[3].type, std::string("uint64_t"));
}
TEST("largest size wins") { const auto f{ guessLayout({ { 8, 1 }, { 8, 4 }, { 8, 2 } }) }; CHECK_EQ(f.size(), std::size_t{ 2 }); CHECK_EQ(f[1].type, std::string("uint32_t")); CHECK_EQ(f[0].type, std::string("uint8_t[8]")); }
TEST("no gaps, no padding") { const auto f{ guessLayout({ { 0, 2 }, { 2, 2 }, { 4, 4 } }) }; CHECK_EQ(f.size(), std::size_t{ 3 }); for (const Field& x : f) CHECK(x.name != "pad"); }
TEST("fields get names from their offsets") { const auto f{ guessLayout({ { 0x1C, 4 } }) }; CHECK_EQ(f.back().offset, 0x1Cu); CHECK(f.back().name != "pad"); CHECK(!f.back().name.empty()); }
TEST("nothing accessed") { CHECK(guessLayout({}).empty()); }

